<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $code
 * @property string $name
 * @property string|null $description
 * @property string $placement
 * @property int $duration_days
 * @property int $price_amount
 * @property string $currency
 * @property bool $is_active
 * @property int $position
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class BoostPackage extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'bst';

    protected $fillable = [
        'code', 'name', 'description', 'placement', 'duration_days', 'price_amount', 'currency', 'is_active',
        'position',
    ];

    protected function casts(): array
    {
        return [
            'is_active' => 'boolean',
        ];
    }

    public function price(): Money
    {
        return Money::of($this->price_amount, $this->currency);
    }
}
